(4917001, 713832, 60862, '<td valign="top">Fascinating curve and tones.</td>', 'Fascinating curve and tones.', '2008-08-28 00:50:06.000000', NULL, 1),
(4917002, 714385, 60862, '<td valign="top">Of all the paper shots, this one stands out.  I really like the high contrast and the shapes and shadows.</td>', 'Of all the paper shots, this one stands out.  I really like the high contrast and the shapes and shadows.', '2008-08-28 00:50:25.000000', NULL, 1),
(4917005, 713180, 60862, '<td valign="top">Very nice.  I would''ve liked it even more with a clean, crisp white circle.  I realize you couldn''t help that, but when you shoot things you don''t control, you just have to accept that they can affect the score.</td>', 'Very nice.  I would''ve liked it even more with a clean, crisp white circle.  I realize you couldn''t help that, but when you shoot things you don''t control, you just have to accept that they can affect the score.', '2008-08-28 00:52:41.000000', NULL, 1),
(4917021, 714405, 60862, '<td valign="top">I think this is a nice image, although I''d like it better if it were really white instead of gray.  But for this challenge, I''m too drawn to the bulb instead of exploring the shapes and textures.</td>', 'I think this is a nice image, although I''d like it better if it were really white instead of gray.  But for this challenge, I''m too drawn to the bulb instead of exploring the shapes and textures.', '2008-08-28 00:59:08.000000', NULL, 1),
(4917023, 714574, 60862, '<td valign="top">Try to make at least one side the full 640 pixels.  This would have more impact at a larger size.</td>', 'Try to make at least one side the full 640 pixels.  This would have more impact at a larger size.', '2008-08-28 00:59:19.000000', NULL, 1),
(4917024, 712844, 60862, '<td valign="top">You''re giving up a lot of impact by not having one side at the maximum allowed 640 pixels.</td>', 'You''re giving up a lot of impact by not having one side at the maximum allowed 640 pixels.', '2008-08-28 00:59:20.000000', NULL, 1),
(4917025, 712728, 60862, '<td valign="top">Remember to use the full 640 pixels allowed for maximum impact.</td>', 'Remember to use the full 640 pixels allowed for maximum impact.', '2008-08-28 00:59:24.000000', NULL, 1),
(4917026, 714031, 60862, '<td valign="top">Without the rabbit, it''s a nice abstract study of shape and tone.  The bunny ruins it for me.  Also, try to always use the max. available size (640 pixels on the long side in this case).</td>', 'Without the rabbit, it''s a nice abstract study of shape and tone.  The bunny ruins it for me.  Also, try to always use the max. available size (640 pixels on the long side in this case).', '2008-08-28 00:59:31.000000', NULL, 1),
