(4918112, 714522, 95361, '<td valign="top">Wonderful picture.  I like the mixture of the textured piece in the middle and the smooth curves on the right and left.  Great job!</td>', 'Wonderful picture.  I like the mixture of the textured piece in the middle and the smooth curves on the right and left.  Great job!', '2008-08-28 16:30:13.000000', NULL, 1),
