(4918122, 714695, 95361, '<td valign="top">I like that it is definately abstract...but I feel like it''s distracting that I can''t find a focal point.  It sure does look cool though.  Good job!</td>', 'I like that it is definately abstract...but I feel like it''s distracting that I can''t find a focal point.  It sure does look cool though.  Good job!', '2008-08-28 16:39:47.000000', NULL, 1),
(4918150, 714685, 97270, '<td valign="top">Now that is what defines an ''abstract'' photograph. It doesnt focus on actual content, but the form. Bravo!!!</td>', 'Now that is what defines an ''abstract'' photograph. It doesnt focus on actual content, but the form. Bravo!!!', '2008-08-28 16:56:12.000000', NULL, 1),
(4918154, 714191, 97270, '<td valign="top">What impressive composition! You caught time in a picture.</td>', 'What impressive composition! You caught time in a picture.', '2008-08-28 16:56:58.000000', NULL, 1),
(4918172, 713192, 29011, '<td valign="top">Perhaps not abstract enough composition wise but I see a glimpse of abstract in the shapes of the ice. (no vote)</td>', 'Perhaps not abstract enough composition wise but I see a glimpse of abstract in the shapes of the ice. (no vote)', '2008-08-28 17:04:46.000000', NULL, 1),
(4918204, 714111, 97270, '<td valign="top">Good theme, but sorry but I fail to see the abstraction in this picture.</td>', 'Good theme, but sorry but I fail to see the abstraction in this picture.', '2008-08-28 17:15:18.000000', NULL, 1),
(4918206, 714478, 97270, '<td valign="top">Sorry but I fail to see the abstraction in this picture. What is abstracted here?</td>', 'Sorry but I fail to see the abstraction in this picture. What is abstracted here?', '2008-08-28 17:15:40.000000', NULL, 1),
(4918212, 713831, 97270, '<td valign="top">Nice composition, but sorry I dont see what is abstracted here. Even the title focusses on the famous celtic stones, when in fact an abstract photograph must focus not on content, but on form.</td>', 'Nice composition, but sorry I dont see what is abstracted here. Even the title focusses on the famous celtic stones, when in fact an abstract photograph must focus not on content, but on form.', '2008-08-28 17:16:53.000000', NULL, 1),
(4918217, 714627, 97270, '<td valign="top">Nice idea, but sorry I dont think this is a pure black and white picture, not even greayscale. I see shades of yellow and tan.</td>', 'Nice idea, but sorry I dont think this is a pure black and white picture, not even greayscale. I see shades of yellow and tan.', '2008-08-28 17:18:04.000000', NULL, 1),
