(4918251, 713807, 74911, '<td valign="top">Great details</td>', 'Great details', '2008-08-28 17:34:20.000000', NULL, 1),
(4918253, 714327, 29011, '<td valign="top">Fun one. Like something on display over in another planet''s musueum. Exhibit A , found strange item floating through space ;) Would take the setup just a bit further and having set something related up in the reflection of the glasses. (no vote)</td>', 'Fun one. Like something on display over in another planet''s musueum. Exhibit A , found strange item floating through space ;) Would take the setup just a bit further and having set something related up in the reflection of the glasses. (no vote)', '2008-08-28 17:34:58.000000', NULL, 1),
(4918254, 714057, 74911, '<td valign="top">Incredible details. A perfect exposure to keep all the details and to still make it stand out.</td>', 'Incredible details. A perfect exposure to keep all the details and to still make it stand out.', '2008-08-28 17:35:02.000000', NULL, 1),
(4918255, 713307, 74911, '<td valign="top">Nice perspective.</td>', 'Nice perspective.', '2008-08-28 17:35:13.000000', NULL, 1),
(4918257, 714692, 29011, '<td valign="top">Looks to be a macro of a microphone. The bits of sensor dust add to the abstract appeal here. Would be interesting to see what others think and how many say "clone it out" ;) (no vote)</td>', 'Looks to be a macro of a microphone. The bits of sensor dust add to the abstract appeal here. Would be interesting to see what others think and how many say "clone it out" ;) (no vote)', '2008-08-28 17:37:07.000000', NULL, 1),
(4918258, 714145, 29011, '<td valign="top">Slinky? The best slinky abstract I could think of. Very well done.<br/>(no vote)</td>', 'Slinky? The best slinky abstract I could think of. Very well done.(no vote)', '2008-08-28 17:39:01.000000', NULL, 1),
