(4918271, 714505, 29011, '<td valign="top">What a beauty. Great work isolating the web with the black background. <br/>(no vote)</td>', 'What a beauty. Great work isolating the web with the black background. (no vote)', '2008-08-28 17:54:27.000000', NULL, 1),
