INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4923615, 714217, 81213, '<td valign="top">Weird... 5/10</td>', 'Weird... 5/10', '2008-08-31 21:29:18.000000', NULL, 1),
(4923617, 713558, 81213, '<td valign="top">Good layout! 5/10</td>', 'Good layout! 5/10', '2008-08-31 21:29:40.000000', NULL, 1),
(4923675, 713960, 43774, '<td valign="top">What is that? Whatever it is, it''s very cool.</td>', 'What is that? Whatever it is, it''s very cool.', '2008-08-31 22:34:05.000000', NULL, 1),
(4923676, 713930, 43774, '<td valign="top">My favourite, very cool.</td>', 'My favourite, very cool.', '2008-08-31 22:34:18.000000', NULL, 1),
(4923679, 714576, 43774, '<td valign="top">Surface tension.....it looks great here.</td>', 'Surface tension.....it looks great here.', '2008-08-31 22:34:39.000000', NULL, 1),
(4923682, 713558, 43774, '<td valign="top">Great for this challenge, good crop/composition to focus on the lines and angles to make this a good abstract image.</td>', 'Great for this challenge, good crop/composition to focus on the lines and angles to make this a good abstract image.', '2008-08-31 22:35:14.000000', NULL, 1),
(4923683, 714230, 43774, '<td valign="top">A great study in lines and angles, good composition.</td>', 'A great study in lines and angles, good composition.', '2008-08-31 22:35:32.000000', NULL, 1),
(4923684, 713499, 43774, '<td valign="top">I''d love to find a staircase like this to photograph, good job.</td>', 'I''d love to find a staircase like this to photograph, good job.', '2008-08-31 22:35:55.000000', NULL, 1),
(4923685, 712762, 43774, '<td valign="top">So very cool. A marble inside a cardboard tube maybe? Your perspective and lighting make this wonderful.</td>', 'So very cool. A marble inside a cardboard tube maybe? Your perspective and lighting make this wonderful.', '2008-08-31 22:36:43.000000', NULL, 1),
(4923686, 713563, 43774, '<td valign="top">The photo is a little small but I really like it.</td>', 'The photo is a little small but I really like it.', '2008-08-31 22:37:03.000000', NULL, 1),
(4923687, 714665, 43774, '<td valign="top">Looking down into a bowl? Excellent perspective.</td>', 'Looking down into a bowl? Excellent perspective.', '2008-08-31 22:37:27.000000', NULL, 1),
(4923688, 712793, 93756, '<td valign="top">This is great. I love how you included the mic stand blurred in the background to give the mic some context.</td>', 'This is great. I love how you included the mic stand blurred in the background to give the mic some context.', '2008-08-31 22:38:30.000000', NULL, 1),
(4923729, 713827, 92847, '<td valign="top">beautiful! it was perfect if you had croped almost in the midle, putting off the top.</td>', 'beautiful! it was perfect if you had croped almost in the midle, putting off the top.', '2008-08-31 23:08:40.000000', NULL, 1),
(4923733, 714326, 90414, '<td valign="top">There are a few zebra abstracts this challenge, but this one was by far the best, and one of the best abstracts in the entire challenge. Great shot!</td>', 'There are a few zebra abstracts this challenge, but this one was by far the best, and one of the best abstracts in the entire challenge. Great shot!', '2008-08-31 23:15:24.000000', NULL, 1),
(4923738, 714689, 90414, '<td valign="top">Very cool, industrial shot.</td>', 'Very cool, industrial shot.', '2008-08-31 23:22:27.000000', NULL, 1),
(4923741, 714229, 90414, '<td valign="top">Looks oof to me and better lighting could have really made this pop.</td>', 'Looks oof to me and better lighting could have really made this pop.', '2008-08-31 23:25:11.000000', NULL, 1),
(4923745, 712793, 90414, '<td valign="top">Shure it is...   (sorry, couldn''t help myself.) Nice dof.</td>', 'Shure it is...   (sorry, couldn''t help myself.) Nice dof.', '2008-08-31 23:28:19.000000', NULL, 1),
(4923751, 713807, 90414, '<td valign="top">Love this composition, well done.</td>', 'Love this composition, well done.', '2008-08-31 23:30:03.000000', NULL, 1),
(4923756, 714358, 90414, '<td valign="top">Interesting lighting and concept, not a typical abstract shot.</td>', 'Interesting lighting and concept, not a typical abstract shot.', '2008-08-31 23:38:49.000000', NULL, 1),
(4923952, 714469, 81362, '<td valign="top">Age old Gestalt question: what is figure and what is ground. Lack of any three dimensional elements makes this so abstract that it could be a stencil as much as a vase. 7 for simplicity and balance.</td>', 'Age old Gestalt question: what is figure and what is ground. Lack of any three dimensional elements makes this so abstract that it could be a stencil as much as a vase. 7 for simplicity and balance.', '2008-09-01 01:13:43.000000', NULL, 1),
(4923981, 714659, 81362, '<td valign="top">Whether vases or elongated light bulbs, the pattern of curves agains a dark background works well. The reflection in the white object on the left has soft dark lines suggestive of umbrella staves. The circular light source goes well with curves, the staves could be taken for window dividing elements, so the distraction isn''t excessive.</td>', 'Whether vases or elongated light bulbs, the pattern of curves agains a dark background works well. The reflection in the white object on the left has soft dark lines suggestive of umbrella staves. The circular light source goes well with curves, the staves could be taken for window dividing elements, so the distraction isn''t excessive.', '2008-09-01 01:18:27.000000', NULL, 1),
(4923992, 713499, 81362, '<td valign="top">Good mixture of tones and elegant abstract shape drawing the eye to the center.</td>', 'Good mixture of tones and elegant abstract shape drawing the eye to the center.', '2008-09-01 01:19:54.000000', NULL, 1),
(4924204, 714404, 67237, '<td valign="top">Amongst the many Irene imitations, this is one of the least accomplished...a bit too much noise in the background, several imperfections in the paper border, asymmetric white(?) line to the frame, etc, etc. The picture deserves a 5 from me, minus 1 point for trying to copy Irene = 4</td>', 'Amongst the many Irene imitations, this is one of the least accomplished...a bit too much noise in the background, several imperfections in the paper border, asymmetric white(?) line to the frame, etc, etc. The picture deserves a 5 from me, minus 1 point for trying to copy Irene = 4', '2008-09-01 02:11:19.000000', NULL, 1),
(4925107, 714569, 72096, '<td valign="top">Interesting shot...you obviously thought that B&amp;W meant the subject, not the medium.  I would have either shown the complete reflection or just the top portion. Clearly, this is a "DP" shot...it should do well.</td>', 'Interesting shot...you obviously thought that B&W meant the subject, not the medium.  I would have either shown the complete reflection or just the top portion. Clearly, this is a "DP" shot...it should do well.', '2008-09-01 09:57:27.000000', NULL, 1),
(4925137, 714627, 72096, '<td valign="top">Very interesting shot...I gave you an 8 because it was slightly not in focus...the picture doesn''t "pop". You could also improve this composition by putting the black swirl in the white stripe and the white swirl in the black. Watch out for those hotspots!!  You should do well in this particular bunch of pictures.</td>', 'Very interesting shot...I gave you an 8 because it was slightly not in focus...the picture doesn''t "pop". You could also improve this composition by putting the black swirl in the white stripe and the white swirl in the black. Watch out for those hotspots!!  You should do well in this particular bunch of pictures.', '2008-09-01 10:06:05.000000', NULL, 1),
(4925138, 713936, 72096, '<td valign="top">Great composition.  I like the high contrast.  The clouds are "popping" in the reflection.  You should do well in this group of pictures.  8</td>', 'Great composition.  I like the high contrast.  The clouds are "popping" in the reflection.  You should do well in this group of pictures.  8', '2008-09-01 10:06:06.000000', NULL, 1),
(4925144, 712762, 72096, '<td valign="top">Great shot!!  8</td>', 'Great shot!!  8', '2008-09-01 10:07:53.000000', NULL, 1),
(4925146, 714691, 72096, '<td valign="top">I thought about making a similar shot.  Very interesting detail.  You should do well in this particular group of pictures!!  8</td>', 'I thought about making a similar shot.  Very interesting detail.  You should do well in this particular group of pictures!!  8', '2008-09-01 10:09:46.000000', NULL, 1),
(4925148, 714293, 72096, '<td valign="top">Finally, someone with an eye for the "abstract".  The title is very fitting!!  I gave you an 8.  Congrats</td>', 'Finally, someone with an eye for the "abstract".  The title is very fitting!!  I gave you an 8.  Congrats', '2008-09-01 10:10:33.000000', NULL, 1),
